330→export async function setupAgents(): Promise<{
331→  agents: Config["agents"];
332→  defaultAgent: string;
333→}> {
334→  const detected = await detectAgents();
335→  const agents: Config["agents"] = {};
336→
337→  if (detected.length > 0) {
338→    for (const agent of detected) {
339→      agents[agent.name] = { command: agent.command, args: [], env: {} };
340→    }
341→  } else {
342→    agents["claude"] = { command: "claude-agent-acp", args: [], env: {} };
343→  }
344→
345→  const defaultAgent = Object.keys(agents)[0];
346→  const agentCmd = agents[defaultAgent].command;
347→  console.log(
348→    ok(`Agent: ${c.bold}${defaultAgent}${c.reset}${c.green} (${agentCmd})`),
349→  );
350→
351→  return { agents, defaultAgent };
352→}
